function U({registerIndicator:g,sourceValues:F,nulls:M}){g({id:"oa-usf",name:"Ultrasmooth Filter (USF)",category:"Filters",placement:"onchart",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"usf",type:"line",title:"UltraSmooth",style:{color:"#ffeb3b",lineWidth:2}}],calc(s,u){const d=Math.max(1,Math.floor(Number(u.length)||20)),o=F(s,u.source||"close"),h=Math.sqrt(2)*Math.PI/d,n=Math.exp(-h),c=2*n*Math.cos(h),r=-n*n,a=(1+c-r)/4,e=new Array(s.length).fill(NaN);for(let t=0;t<s.length;t++){const N=o[t],l=t>0?o[t-1]:NaN,m=t>1?o[t-2]:NaN,f=Number.isFinite(N)?N:l,i=Number.isFinite(l)?l:f,p=Number.isFinite(m)?m:i,b=t>0?e[t-1]:NaN,y=t>1?e[t-2]:NaN,x=Number.isFinite(b)?b:i,S=Number.isFinite(y)?y:p;e[t]=(1-a)*f+(2*a-c)*i-(a+r)*p+c*x+r*S}return{usf:M(e)}}})}export{U as default};
